// Classe les chunks par proximité au vecteur `query`, renvoie les k premiers ids.
// TODO : ceci trie par PRODUIT SCALAIRE brut, donc un vecteur de grande
//        magnitude gagne même s'il pointe dans la mauvaise direction.
//        La cosinus divise par la norme : c'est l'ORIENTATION qui compte.
export function rankByCosine(query, chunks, k) {
  const dot = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);
  const scored = chunks.map((c) => ({ id: c.id, s: dot(query, c.vec) }));
  scored.sort((a, b) => b.s - a.s || (a.id < b.id ? -1 : 1));
  return scored.slice(0, k).map((x) => x.id);
}

